"""A tiny chess game engine."""

from __future__ import annotations

from dataclasses import dataclass

FILES = "abcdefgh"
RANKS = "87654321"
PIECES = {"p", "r", "n", "b", "q", "k"}


@dataclass(frozen=True, slots=True)
class Move:
    start: str
    end: str


class ChessError(ValueError):
    pass


def initial_board() -> list[list[str | None]]:
    board: list[list[str | None]] = [[None for _ in range(8)] for _ in range(8)]
    back_rank = ["r", "n", "b", "q", "k", "b", "n", "r"]
    board[0] = [p.upper() for p in back_rank]
    board[1] = ["P"] * 8
    board[6] = ["p"] * 8
    board[7] = back_rank[:]
    return board


def parse_square(square: str) -> tuple[int, int]:
    if len(square) != 2 or square[0] not in FILES or square[1] not in RANKS:
        raise ChessError(f"invalid square: {square}")
    return 8 - int(square[1]), FILES.index(square[0])


def render(board: list[list[str | None]]) -> str:
    rows = []
    for rank, row in zip(RANKS, board):
        rows.append(f"{rank} " + " ".join(piece or "." for piece in row))
    rows.append("  " + " ".join(FILES))
    return "\n".join(rows)


def move_piece(board: list[list[str | None]], move: Move) -> None:
    sr, sc = parse_square(move.start)
    er, ec = parse_square(move.end)
    piece = board[sr][sc]
    if piece is None:
        raise ChessError(f"no piece on {move.start}")
    board[er][ec] = piece
    board[sr][sc] = None


def parse_move(text: str) -> Move:
    text = text.strip().lower().replace(" ", "")
    if len(text) != 4:
        raise ChessError(f"invalid move: {text}")
    return Move(text[:2], text[2:])


def play(moves: list[str]) -> list[list[str | None]]:
    board = initial_board()
    for move in moves:
        move_piece(board, parse_move(move))
    return board

from toybox.chess import ChessError, initial_board, parse_move, play, render


def test_initial_board_renders() -> None:
    board = initial_board()
    text = render(board)
    assert "8 r n b q k b n r" in text
    assert "1 R N B Q K B N R" in text


def test_parse_move() -> None:
    move = parse_move("e2e4")
    assert move.start == "e2"
    assert move.end == "e4"


def test_play_moves_a_piece() -> None:
    board = play(["e2e4"])
    assert board[6][4] is None
    assert board[4][4] == "P"


def test_move_from_empty_square_errors() -> None:
    try:
        play(["e3e4"])
    except ChessError:
        return
    raise AssertionError("expected ChessError")

